<?php
declare(strict_types=1);require_once __DIR__.'/config/ai_analytics.php';
$error=null;$current=[];$previous=[];$daily=[];$recommendations=[];
function aqt_range(PDO $pdo,int $orgId,string $from,string $to):array{$s=$pdo->prepare("SELECT event_type,COUNT(*) total,COUNT(DISTINCT session_token) sessions FROM public_ai_events WHERE organization_id=? AND created_at>=? AND created_at<? GROUP BY event_type");$s->execute([$orgId,$from,$to]);$e=[];foreach($s->fetchAll() as $r)$e[(string)$r['event_type']=(int)$r['total'];$opens=$e['panel_open']??0;$helpful=$e['answer_helpful']??0;$unanswered=$e['answer_unanswered']??0;$handoff=$e['human_handoff']??0;$feedback=$helpful+$unanswered;return ['opens'=>$opens,'helpful'=>$helpful,'unanswered'=>$unanswered,'handoff'=>$handoff,'helpful_rate'=>$feedback?round($helpful/$feedback*100,1):0,'unanswered_rate'=>$feedback?round($unanswered/$feedback*100,1):0,'handoff_rate'=>$opens?round($handoff/$opens*100,1):0];}
function aqt_delta(float $now,float $before):string{if($before==0)return $now>0?'+100%':'0%';$v=round(($now-$before)/$before*100,1);return ($v>0?'+':'').$v.'%';}
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}$orgId=pscms_org_id($pdo);$today=new DateTimeImmutable('today');$thisStart=$today->modify('-6 days');$prevStart=$thisStart->modify('-7 days');$current=aqt_range($pdo,$orgId,$thisStart->format('Y-m-d 00:00:00'),$today->modify('+1 day')->format('Y-m-d 00:00:00'));$previous=aqt_range($pdo,$orgId,$prevStart->format('Y-m-d 00:00:00'),$thisStart->format('Y-m-d 00:00:00'));
 $s=$pdo->prepare("SELECT DATE(created_at) day,SUM(event_type='panel_open') opens,SUM(event_type='answer_helpful') helpful,SUM(event_type='answer_unanswered') unanswered,SUM(event_type='human_handoff') handoffs FROM public_ai_events WHERE organization_id=? AND created_at>=? GROUP BY DATE(created_at) ORDER BY day");$s->execute([$orgId,$today->modify('-13 days')->format('Y-m-d 00:00:00')]);$byDay=[];foreach($s->fetchAll() as $r)$byDay[(string)$r['day']]=$r;for($i=13;$i>=0;$i--){$d=$today->modify('-'.$i.' days')->format('Y-m-d');$daily[]=$byDay[$d]??['day'=>$d,'opens'=>0,'helpful'=>0,'unanswered'=>0,'handoffs'=>0];}
 if($current['opens']===0)$recommendations[]=['Start collecting live signals','No assistant opens were recorded this week. Confirm the public AI button and event endpoint after pulling the update.','setup'];
 if($current['unanswered_rate']>=25)$recommendations[]=['Prioritise unanswered questions','The unanswered feedback rate is high. Review the AI Knowledge Manager queue and publish verified answers for repeated questions.','urgent'];
 if($current['handoff_rate']>=30)$recommendations[]=['Reduce avoidable handoffs','Many sessions move to human support. Improve verified service, membership and product answers before the next retraining.','attention'];
 if($current['helpful_rate']>0&&$current['helpful_rate']<70)$recommendations[]=['Improve answer usefulness','Helpful feedback is below 70%. Check fallback wording, top topics and recently published answers.','attention'];
 if($current['unanswered']>$previous['unanswered'])$recommendations[]=['Unanswered trend increased','This week has more unanswered reports than last week. Resolve the newest queue before retraining.','urgent'];
 if(!$recommendations)$recommendations[]=['Quality signals look stable','No threshold-based issue was detected. Continue reviewing new questions and retrain when the health dashboard recommends it.','good'];
}catch(Throwable $e){$error=$e->getMessage();}
function aqh(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
$maxOpen=max(1,...array_map(static fn(array $r):int=>(int)$r['opens'],$daily));
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>AI Quality Trends</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>.qt-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.qt-kpi,.qt-card{padding:17px;border:1px solid #dce7e0;border-radius:16px;background:#fff}.qt-kpi small,.qt-kpi strong,.qt-kpi span{display:block}.qt-kpi strong{margin:5px 0;font-size:1.7rem}.qt-kpi span{font-size:.68rem;color:#6d7e74}.qt-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:14px}.qt-chart{display:flex;align-items:flex-end;gap:7px;height:230px;padding:18px 5px 0;border-bottom:1px solid #dce6e0}.qt-day{display:grid;grid-template-rows:1fr auto;align-items:end;flex:1;height:100%;text-align:center}.qt-bar{width:100%;min-height:3px;border-radius:7px 7px 2px 2px;background:linear-gradient(#24a868,#157649)}.qt-day small{margin-top:7px;color:#738278;font-size:.56rem}.qt-rec{margin-top:10px;padding:13px;border-left:4px solid #d49a32;border-radius:10px;background:#fff8e9}.qt-rec.urgent{border-color:#c65545;background:#fff1ee}.qt-rec.good{border-color:#258353;background:#eef9f2}.qt-rec b,.qt-rec span{display:block}.qt-rec span{margin-top:4px;color:#61736a;font-size:.72rem;line-height:1.5}.qt-compare{width:100%;border-collapse:collapse}.qt-compare th,.qt-compare td{padding:10px;border-bottom:1px solid #e4ece7;text-align:left;font-size:.74rem}.qt-compare th{color:#63766b}@media(max-width:900px){.qt-kpis{grid-template-columns:repeat(2,1fr)}.qt-grid{grid-template-columns:1fr}}@media(max-width:560px){.qt-kpis{grid-template-columns:1fr}.qt-chart{gap:3px}.qt-day small{font-size:.48rem}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>AI Quality Trends</small></span></a><div class="os-top-actions"><a class="os-btn" href="ai_improvement_dashboard.php">Analytics</a><a class="os-btn" href="ai_training_health.php">Training Health</a><a class="os-btn primary" href="ai_knowledge_manager.php">Knowledge Manager</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero"><div class="os-kicker">WEEKLY QUALITY INTELLIGENCE</div><h1>See whether AI conversations are improving.</h1><p>Every comparison uses recorded visitor feedback and assistant events. Zero data remains zero; no estimated performance is displayed.</p></section><?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=aqh($error)?></div><?php endif;?><section class="qt-kpis"><article class="qt-kpi"><small>Assistant Opens</small><strong><?=(int)($current['opens']??0)?></strong><span><?=aqt_delta((float)($current['opens']??0),(float)($previous['opens']??0))?> vs previous week</span></article><article class="qt-kpi"><small>Helpful Rate</small><strong><?=number_format((float)($current['helpful_rate']??0),1)?>%</strong><span><?=aqt_delta((float)($current['helpful_rate']??0),(float)($previous['helpful_rate']??0))?> vs previous week</span></article><article class="qt-kpi"><small>Unanswered Rate</small><strong><?=number_format((float)($current['unanswered_rate']??0),1)?>%</strong><span><?=aqt_delta((float)($current['unanswered_rate']??0),(float)($previous['unanswered_rate']??0))?> vs previous week</span></article><article class="qt-kpi"><small>Human Handoff Rate</small><strong><?=number_format((float)($current['handoff_rate']??0),1)?>%</strong><span><?=aqt_delta((float)($current['handoff_rate']??0),(float)($previous['handoff_rate']??0))?> vs previous week</span></article></section><section class="qt-grid"><article class="qt-card"><h2>14-Day Assistant Engagement</h2><div class="qt-chart"><?php foreach($daily as $r):$height=max(2,round((int)$r['opens']/$maxOpen*100));?><div class="qt-day" title="<?=aqh((string)$r['day'])?>: <?=(int)$r['opens']?> opens"><div class="qt-bar" style="height:<?=$height?>%"></div><small><?=date('d M',strtotime((string)$r['day']))?></small></div><?php endforeach;?></div><h2 style="margin-top:22px">Weekly Comparison</h2><table class="qt-compare"><thead><tr><th>Metric</th><th>This week</th><th>Previous week</th></tr></thead><tbody><tr><td>Helpful feedback</td><td><?=(int)($current['helpful']??0)?></td><td><?=(int)($previous['helpful']??0)?></td></tr><tr><td>Unanswered reports</td><td><?=(int)($current['unanswered']??0)?></td><td><?=(int)($previous['unanswered']??0)?></td></tr><tr><td>Human handoffs</td><td><?=(int)($current['handoff']??0)?></td><td><?=(int)($previous['handoff']??0)?></td></tr></tbody></table></article><article class="qt-card"><h2>Smart Recommendations</h2><p style="color:#6b7d73;font-size:.72rem">Generated from transparent thresholds, not medical or product assumptions.</p><?php foreach($recommendations as $r):?><div class="qt-rec <?=aqh($r[2])?>"><b><?=aqh($r[0])?></b><span><?=aqh($r[1])?></span></div><?php endforeach;?></article></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
